public class Main {
    static int n, t;
    static long[][][][][] dp;
    // dp[pos][lastY][dir+1][peaks][valleys]
    // dir: -1 (down), 0 (none), 1 (up) -> index dir+1 in [0..2]

    static long solve(int pos, int lastY, int dir, int peaks, int valleys) {
        if (peaks > t || valleys > t - 1) return 0;
        if (pos == n) {
            return (peaks == t && valleys == t - 1) ? 1 : 0;
        }
        if (dp[pos][lastY][dir + 1][peaks][valleys] != -1)
            return dp[pos][lastY][dir + 1][peaks][valleys];

        long res = 0;
        for (int y = 1; y <= 4; y++) {
            if (y == lastY) continue; // no horizontal segment
            int newDir = (y > lastY) ? 1 : -1;
            int newPeaks = peaks;
            int newValleys = valleys;

            if (dir != 0 && newDir != dir) {
                if (dir == 1 && newDir == -1) newPeaks++;
                else if (dir == -1 && newDir == 1) newValleys++;
            }

            res += solve(pos + 1, y, newDir, newPeaks, newValleys);
        }

        dp[pos][lastY][dir + 1][peaks][valleys] = res;
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        dp = new long[n + 1][5][3][t + 1][t]; // valleys up to t-1, index 0..t-1
        for (int i = 0; i <= n; i++)
            for (int j = 0; j <= 4; j++)
                for (int d = 0; d < 3; d++)
                    for (int p = 0; p <= t; p++)
                        Arrays.fill(dp[i][j][d][p], -1);

        long ans = 0;
        // choose y1
        for (int y1 = 1; y1 <= 4; y1++) {
            // choose y2 != y1 to define initial direction
            for (int y2 = 1; y2 <= 4; y2++) {
                if (y2 == y1) continue;
                int dir = (y2 > y1) ? 1 : -1;
                ans += solve(2, y2, dir, 0, 0);
            }
        }
        System.out.println(ans);
    }
}

