public class Main {
    static int n, t;
    static long[][][][] dp;

    // dp[pos][lastY][peaks][valleys][trend]
    // trend: 0 = unknown/start, 1 = up, 2 = down

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        dp = new long[n + 1][5][t + 1][t][3];

        // Initialize for position 1: choose y1 in [1..4]
        for (int y = 1; y <= 4; y++) {
            dp[1][y][0][0][0] = 1;
        }

        for (int pos = 1; pos < n; pos++) {
            for (int lastY = 1; lastY <= 4; lastY++) {
                for (int peaks = 0; peaks <= t; peaks++) {
                    for (int valleys = 0; valleys < t; valleys++) {
                        for (int trend = 0; trend < 3; trend++) {
                            long cur = dp[pos][lastY][peaks][valleys][trend];
                            if (cur == 0) continue;

                            for (int nextY = 1; nextY <= 4; nextY++) {
                                if (nextY == lastY) continue; // no horizontal segment

                                int newTrend;
                                if (nextY > lastY) newTrend = 1;
                                else newTrend = 2;

                                int newPeaks = peaks;
                                int newValleys = valleys;

                                if (trend == 1 && newTrend == 2) {
                                    // up then down -> peak at pos
                                    newPeaks++;
                                } else if (trend == 2 && newTrend == 1) {
                                    // down then up -> valley at pos
                                    newValleys++;
                                }

                                if (newPeaks > t || newValleys >= t) continue;

                                dp[pos + 1][nextY][newPeaks][newValleys][newTrend] += cur;
                            }
                        }
                    }
                }
            }
        }

        long ans = 0;
        for (int lastY = 1; lastY <= 4; lastY++) {
            for (int trend = 1; trend <= 2; trend++) {
                ans += dp[n][lastY][t][t - 1][trend];
            }
        }

        System.out.println(ans);
    }
}

