public class Main {
    static int n, t;
    static long[][][][] dp;

    // pos: current position (1..n)
    // last: last y value (1..4)
    // peaks: number of peaks so far
    // valleys: number of valleys so far
    static long solve(int pos, int last, int peaks, int valleys) {
        if (pos == n) {
            return (peaks == t && valleys == t - 1) ? 1 : 0;
        }
        if (dp[pos][last][peaks][valleys] != -1) {
            return dp[pos][last][peaks][valleys];
        }

        long res = 0;
        for (int next = 1; next <= 4; next++) {
            if (next == last) continue; // no horizontal segment

            int newPeaks = peaks;
            int newValleys = valleys;

            if (pos >= 2) {
                // we know y_{pos-1} = last, y_pos = next
                // need y_{pos-2}, but we don't store it directly.
                // Instead, we reconstruct using direction changes:
                // This is impossible without more state, so we must
                // store previous y as well. Restart design.
            }
        }

        return dp[pos][last][peaks][valleys] = res;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        t = fs.nextInt();

        // We need to track last two y-values to detect peaks/valleys.
        // State: pos, y_{pos-1}, y_{pos}, peaks, valleys
        // pos >= 2 for this state; we will handle initialization separately.

        // Dimensions:
        // pos: 2..n (we'll index 0..n, but use from 2)
        // yPrev, yCur: 1..4
        // peaks: 0..t
        // valleys: 0..t-1 (max)
        long[][][][][] dp2 = new long[n + 1][5][5][t + 1][t + 1];

        // Initialize with -1
        for (int i = 0; i <= n; i++)
            for (int a = 0; a <= 4; a++)
                for (int b = 0; b <= 4; b++)
                    for (int c = 0; c <= t; c++)
                        Arrays.fill(dp2[i][a][b][c], -1);

        // Recursive with memo
        long ans = 0;

        // We choose y1 and y2 first (no horizontals)
        for (int y1 = 1; y1 <= 4; y1++) {
            for (int y2 = 1; y2 <= 4; y2++) {
                if (y2 == y1) continue;
                ans += dfs(2, y1, y2, 0, 0, dp2);
            }
        }

        System.out.println(ans);
    }

    static long dfs(int pos, int yPrev, int yCur, int peaks, int valleys,
                    long[][][][][] dp2) {
        if (pos == n) {
            return (peaks == t && valleys == t - 1) ? 1 : 0;
        }
        if (dp2[pos][yPrev][yCur][peaks][valleys] != -1) {
            return dp2[pos][yPrev][yCur][peaks][valleys];
        }

        long res = 0;
        for (int next = 1; next <= 4; next++) {
            if (next == yCur) continue; // no horizontal segment

            int newPeaks = peaks;
            int newValleys = valleys;

            // Check if yCur is a peak or valley
            if (yPrev < yCur && yCur > next) {
                newPeaks++;
                if (newPeaks > t) continue;
            } else if (yPrev > yCur && yCur < next) {
                newValleys++;
                if (newValleys > t - 1) continue;
            }

            res += dfs(pos + 1, yCur, next, newPeaks, newValleys, dp2);
        }

        dp2[pos][yPrev][yCur][peaks][valleys] = res;
        return res;
    }

    // Simple fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

