public class Main {
    static int n, t;
    static long[][][][] dp;
    static boolean[][][][] vis;

    static long solve(int pos, int lastY, int peaks, int valleys) {
        if (pos == n) {
            return (peaks == t && valleys == t - 1) ? 1 : 0;
        }
        if (vis[pos][lastY][peaks][valleys]) return dp[pos][lastY][peaks][valleys];
        vis[pos][lastY][peaks][valleys] = true;

        long res = 0;
        for (int y = 1; y <= 4; y++) {
            if (y == lastY) continue; // no horizontal segment
            int newPeaks = peaks;
            int newValleys = valleys;
            if (pos >= 2) {
                int prevY = lastY;
                int prevPrevY = -1; // we don't know here, so we handle differently
            }
        }
        return dp[pos][lastY][peaks][valleys] = res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        // We'll use DP over full states: position, y[pos-1], y[pos-2], peaks, valleys
        // Because to determine if pos-1 is peak/valley when placing y[pos], we need y[pos-2], y[pos-1], y[pos].
        // Constraints are small: n<=20, y in [1..4], peaks<=10, valleys<=9.
        // State count: n(20)*4*4*11*10 = 35200, transitions 4 each -> fine.

        long[][][][][] dp2 = new long[n + 1][5][5][t + 1][t]; // valleys max t-1
        boolean[][][][][] vis2 = new boolean[n + 1][5][5][t + 1][t];

        // Initialize for position 1: choose y1 in [1..4]
        for (int y1 = 1; y1 <= 4; y1++) {
            dp2[1][y1][0][0][0] = 1;
            vis2[1][y1][0][0][0] = true;
        }

        for (int pos = 2; pos <= n; pos++) {
            for (int last = 1; last <= 4; last++) {
                for (int prev = 0; prev <= 4; prev++) {
                    for (int peaks = 0; peaks <= t; peaks++) {
                        for (int valleys = 0; valleys < t; valleys++) {
                            if (!vis2[pos - 1][last][prev][peaks][valleys]) continue;
                            long cur = dp2[pos - 1][last][prev][peaks][valleys];
                            for (int y = 1; y <= 4; y++) {
                                if (y == last) continue; // no horizontal
                                int newPeaks = peaks;
                                int newValleys = valleys;
                                if (pos >= 3) {
                                    int yPrev = last;
                                    int yPrevPrev = prev;
                                    if (yPrevPrev < yPrev && yPrev > y) newPeaks++;
                                    if (yPrevPrev > yPrev && yPrev < y) newValleys++;
                                    if (newPeaks > t || newValleys > t - 1) continue;
                                }
                                int newPrev = last;
                                int newLast = y;
                                if (!vis2[pos][newLast][newPrev][newPeaks][newValleys]) {
                                    vis2[pos][newLast][newPrev][newPeaks][newValleys] = true;
                                    dp2[pos][newLast][newPrev][newPeaks][newValleys] = 0;
                                }
                                dp2[pos][newLast][newPrev][newPeaks][newValleys] += cur;
                            }
                        }
                    }
                }
            }
        }

        long ans = 0;
        for (int last = 1; last <= 4; last++) {
            for (int prev = 0; prev <= 4; prev++) {
                if (vis2[n][last][prev][t][t - 1]) {
                    ans += dp2[n][last][prev][t][t - 1];
                }
            }
        }
        System.out.println(ans);
    }
}
